import os
import json
from typing import Dict, Any, Optional
from google.cloud import documentai_v1 as documentai

def extract_and_validate_document(
    project_id: str,
    location: str,
    processor_id: str,
    file_path: str,
    mime_type: str,
    required_fields: list
) -> Dict[str, Any]:
    """
    Extract structured data from a document using Google Cloud Document AI
    and validate required fields with confidence scores.
    """
    client = documentai.DocumentProcessorServiceClient()
    processor_name = client.processor_path(project_id, location, processor_id)

    with open(file_path, "rb") as file:
        file_content = file.read()

    raw_document = documentai.RawDocument(content=file_content, mime_type=mime_type)
    request = documentai.ProcessRequest(name=processor_name, raw_document=raw_document)
    result = client.process_document(request=request)
    document = result.document

    extracted_data = {}
    validation_results = {
        "missing_fields": [],
        "low_confidence_fields": [],
        "valid_fields": [],
        "all_fields": {}
    }

    for entity in document.entities:
        field_name = entity.type_
        field_value = entity.mention_text
        confidence = entity.confidence

        extracted_data[field_name] = {
            "value": field_value,
            "confidence": confidence
        }

        validation_results["all_fields"][field_name] = {
            "value": field_value,
            "confidence": confidence
        }

        if field_name in required_fields:
            if confidence >= 0.8:
                validation_results["valid_fields"].append(field_name)
            else:
                validation_results["low_confidence_fields"].append({
                    "field": field_name,
                    "confidence": confidence,
                    "value": field_value
                })

    for field in required_fields:
        if field not in extracted_data:
            validation_results["missing_fields"].append(field)

    validation_results["is_valid"] = (
        len(validation_results["missing_fields"]) == 0 and
        len(validation_results["low_confidence_fields"]) == 0
    )

    return validation_results
